function header(active='home'){return `<div class="wrap"><header class="site-header"><a class="wordmark" href="#home" data-screen="home"><span class="wordmark-symbol">f</span><span><span class="wordmark-title">萤火手记</span><span class="wordmark-small">FIREFLY / FIELD NOTES</span></span></a><nav class="site-nav" aria-label="网站导航"><a href="#home" data-screen="home" ${active==='home'?'aria-current="page"':''}>首页</a><a href="#entries" data-home-type="">文章</a><a href="#archive" data-modal="archive">归档</a><a href="#diary" data-home-type="DIARY">日记</a><a href="#resources" class="nav-optional" data-modal="resources">资源</a><a href="#about" class="nav-optional" data-modal="about">关于</a></nav><div class="header-tools"><button class="icon-button" data-action="search" aria-label="搜索文章">${icon('search')}</button><button class="icon-button mobile-menu" data-action="menu" aria-label="展开导航菜单" aria-expanded="false">${icon('menu')}</button></div></header></div>`}
function footer(){return `<footer class="site-footer"><div><p class="footer-name">萤火手记 · firefly1v</p><p>记录学习、思考与生活。让每一点微光，都有迹可循。</p></div><div class="row"><span>© 2026 · 示例样稿</span><a href="https://github.com/InInNHD/PersonalWebsite2" target="_blank" rel="noopener noreferrer">GitHub ↗</a><a href="#editor" data-screen="editor">内容管理</a></div></footer>`}
function tags(list){return list.map(tag=>`<a class="tag" href="#entries" data-tag-search="${escapeHtml(tag)}">#${escapeHtml(tag)}</a>`).join('')}
function card(post,featured=false){return `<article class="post-card ${featured?'featured':''}"><a href="#article" data-post="${post.id}" class="cover" aria-label="阅读：${escapeHtml(post.title)}">${cover(post.cover,post.title)}<span class="cover-label">${post.cover.toUpperCase()} / 0${post.id}</span></a><div class="post-content"><div class="row"><span class="badge">${featured?'↟ 置顶精选':typeNames[post.type]}</span><span class="meta">${post.category}</span></div><h3><a href="#article" data-post="${post.id}">${escapeHtml(post.title)}</a></h3><p>${escapeHtml(post.summary)}</p><div class="meta"><time>${post.date}</time><span>·</span><span>约 ${post.minutes} 分钟</span></div><div class="post-bottom"><div class="tags">${tags(post.tags)}</div><a href="#article" data-post="${post.id}" aria-label="阅读全文：${escapeHtml(post.title)}">${icon('arrow')}</a></div></div></article>`}
function home(){const filtered=posts.filter(p=>(!state.type||p.type===state.type)&&(!state.category||p.category===state.category)&&(!state.keyword||[p.title,p.summary,...p.tags].join(' ').toLowerCase().includes(state.keyword.toLowerCase())))
 return `${header()}<main class="wrap"><section class="hero" aria-labelledby="hero-title"><div><div class="eyebrow">A PERSONAL NOTEBOOK, ALWAYS GROWING</div><h1 id="hero-title">把思考留下，<br>让<span>知识生长。</span></h1><p class="description">你好，我是 firefly1v。<br>在这里整理学习中的发现，也收藏生活里的微光。</p><div class="hero-actions"><a class="btn primary" href="#entries" data-home-type="NOTE">阅读笔记 ${icon('arrow')}</a><a class="btn" href="#entries" data-home-type="DIARY">浏览日记</a></div><p class="hero-sign">LEARN SOMETHING. KEEP A LITTLE LIGHT.</p></div><div class="hero-art">${heroArt()}<span class="art-caption">FIREFLY LAB / SKETCH 001</span></div></section>
 <div class="content-layout"><section id="entries" aria-labelledby="entries-title"><div class="section-heading"><h2 id="entries-title">最近的记录<span class="accent">.</span></h2><small>${String(filtered.length).padStart(2,'0')} ENTRIES / 示例</small></div><div class="content-tools" role="group" aria-label="文章栏目">${[['','全部'],['NOTE','笔记'],['THOUGHT','心得'],['DIARY','日记']].map(([value,label])=>`<button class="type-tab ${state.type===value?'active':''}" data-type="${value}" aria-pressed="${state.type===value}">${label}</button>`).join('')}<button class="filter-toggle" aria-label="筛选文章" data-action="filters" aria-expanded="${state.filters}" aria-controls="filters">${icon('filter')}<span class="filter-word">筛选</span>${state.category||state.keyword?'<span class="accent">●</span>':''}</button></div>
 <form id="filters" class="filters" ${state.filters?'':'hidden'}><label>标题、摘要或标签<input name="keyword" type="search" value="${escapeHtml(state.keyword)}" placeholder="例如：Java、知识整理"></label><label>分类<select name="category"><option value="">全部分类</option>${[...new Set(posts.map(p=>p.category))].map(c=>`<option ${state.category===c?'selected':''}>${c}</option>`).join('')}</select></label><button type="submit" class="btn primary small">查找</button><button type="button" class="btn small" data-action="clear">清空</button></form>
 <div class="article-grid">${filtered.length?filtered.map((p,i)=>card(p,i===0&&p.pinned&&!state.type)).join(''):`<div class="empty-state">${icon('search')}<h3>暂时没有找到这条记录</h3><p>试试其他关键词，或清空当前筛选。</p><button class="btn small" data-action="clear">清空筛选</button></div>`}</div>${filtered.length?`<nav class="pagination" aria-label="文章分页"><button class="page-number" disabled aria-label="上一页">‹</button><button class="page-number active" aria-current="page">1</button><button class="page-number" disabled aria-label="下一页">›</button><span class="meta">共 ${filtered.length} 篇</span></nav>`:''}</section>
 <aside class="home-sidebar"><section class="side-profile"><div class="avatar" aria-label="原创字母 f 头像">f</div><h3>firefly1v<span class="accent">_</span></h3><span class="eyebrow" style="font-size:9px">LEARNING IN PUBLIC</span><p>把零散的知识连成线，<br>把普通的日子写成篇。</p><div class="side-stats"><div><strong>06</strong><small>篇示例记录</small></div><div><strong>03</strong><small>个栏目</small></div><div><strong>05</strong><small>个分类</small></div></div><div class="socials"><a href="https://github.com/InInNHD/PersonalWebsite2" target="_blank" rel="noopener noreferrer">${icon('github')}GitHub ↗</a><span class="spacer"></span><button class="tag" data-modal="about">关于我 →</button></div></section><section class="side-section"><h3>${icon('book')} 在这里探索</h3>${[['Java','01'],['Spring Boot','01'],['MySQL','01'],['学习方法','02'],['生活记录','01']].map(([label,n])=>`<a class="category-link" href="#entries" data-category="${label}"><span>${label}</span><span>${n}</span></a>`).join('')}</section><section class="side-section"><p class="side-quote">不必一次照亮整条路，<br>记住今天走过的这一段。</p><p class="side-label">A NOTE TO MYSELF / 示例文案</p></section></aside></div>${footer()}</main>`}

function highlighted(code){return escapeHtml(code).split('\n').map(line=>line.trim().startsWith('//')?`<span class="syntax-comment">${line}</span>`:line.replace(/(&quot;.*?&quot;)/g,'<span class="syntax-string">$1</span>').replace(/\b(public|return|long|const)\b/g,'<span class="syntax-key">$1</span>')).join('\n')}
function codeBlock(code=sampleCode){return `<div class="code-block"><div class="code-header"><span>JAVA · ArticleController.java</span><button type="button" data-action="copy-code">复制代码</button></div><pre><code>${highlighted(code)}</code></pre></div>`}
const flowSvg=()=>`<svg viewBox="0 0 660 150" role="img" aria-label="请求流程：浏览器到接口到数据库，再返回结果"><g fill="none" stroke="#6b8e78" stroke-width="1.3"><rect x="20" y="37" width="160" height="76" rx="9"/><rect x="250" y="37" width="160" height="76" rx="9"/><rect x="480" y="37" width="160" height="76" rx="9"/><path d="M190 62h48m-7-5 7 5-7 5m189 0h48m-7-5 7 5-7 5M468 91h-48m7-5-7 5 7 5m-189 0h-48m7-5-7 5 7 5"/></g><g font-family="Microsoft YaHei, sans-serif" font-size="15" fill="#d7e4da" text-anchor="middle"><text x="100" y="70">浏览器</text><text x="330" y="70">Spring Boot</text><text x="560" y="70">MySQL</text></g><g font-family="monospace" font-size="10" fill="#8ca499" text-anchor="middle"><text x="100" y="94">Vue / fetch</text><text x="330" y="94">Controller / Service</text><text x="560" y="94">read / write</text></g></svg>`
function articleBody(post){
 if(post.id===1)return `<p>学习前后端分离时，我最想弄清楚的，并不是某一个注解的写法，而是：<strong>页面上的一次点击，究竟怎样变成数据库里的一条记录？</strong></p><p>把这个过程拆开，很多零散的知识就能连在一起。这篇示例笔记从一次文章查询开始，梳理三个最重要的环节。</p><h2 id="part-1"><span class="section-no">01</span>一次请求的旅程</h2><p>浏览器负责展示和交互；后端接收请求，判断可以返回哪些内容；数据库负责保存和读取记录。每一层都有自己的职责。</p><figure class="flow-art"><button data-action="zoom-flow" aria-label="放大查看请求流程图">${flowSvg()}</button><figcaption class="flow-caption">一次文章查询的数据流 · 点击放大查看</figcaption></figure><p>例如，点击一篇笔记时，前端带着文章编号请求接口。后端确认它已经公开，再把正文、分类和标签一起返回给页面。</p><h2 id="part-2"><span class="section-no">02</span>给接口一份清晰的约定</h2><p>接口是一份共同遵守的约定。路径描述资源，方法表达操作，状态码说明请求的结果。先约定好这些细节，前后端才能各自推进。</p>${codeBlock()}<div class="callout">把“是否公开”的判断留在后端。访客页面即使隐藏了草稿入口，也不能代替接口上的内容隔离。</div><div class="table-scroll"><table><thead><tr><th>状态码</th><th>含义</th><th>页面处理</th></tr></thead><tbody><tr><td>200</td><td>读取成功</td><td>展示文章</td></tr><tr><td>404</td><td>不存在或未公开</td><td>提供返回入口</td></tr><tr><td>503</td><td>服务暂不可用</td><td>提示重试</td></tr></tbody></table></div><h2 id="part-3"><span class="section-no">03</span>把错误当作流程的一部分</h2><p>网络请求不一定成功。加载、空内容和错误，都应该成为页面设计的一部分，而不是在开发结束时才补上的提示。</p><ul><li>加载中，让用户知道页面正在等待什么。</li><li>没有内容时，解释原因，并提供可以继续的入口。</li><li>请求失败时，保留必要上下文，让用户能够重试。</li></ul><p>先把一条数据流走通，再逐步打磨它的每一个状态。代码里的边界更清楚，页面上的体验也会更从容。</p>`
 const bodies={
 2:['先写下问题','为知识建立连接','留下一条可复用的路径','一条有用的笔记，通常从具体的问题开始。记录当时的场景，比收集更多术语更容易帮助未来的自己。','把相似的问题放在一起，也给不同领域的知识留一个彼此指向的入口。分类与标签的意义，来自真实的关联。','结束一篇笔记前，补上一段自己的总结和一个可操作的检查方法。让下一次查阅可以直接开始。'],
 3:['从使用场景出发','理解数据结构的取舍','用小例子验证选择','选择集合之前，先想清楚：需要按顺序遍历，还是按键查找？允许重复吗？数据会频繁修改吗？','列表、集合与映射各自服务不同的问题。把它们放到真实的数据流里，比单独记忆接口更有帮助。','用少量明确的输入检查行为，再根据实际性能表现调整。知道为什么选择，比记住一个固定答案更重要。'],
 4:['一个普通的下午','走慢一点看到什么','留给今天的一句话','傍晚出去走了一小段路。风比前几天凉，树影从人行道的一边移到了另一边。没有特别的目的地。','有时把脚步放慢，才会发现一天并没有真的一闪而过。那些很小的声音和光线，也在构成生活。','把愿意分享的一点感受留下。更多没有想清楚的事，就让它们暂时保持原来的样子。'],
 5:['先看见真正的问题','读懂查询计划','验证优化的结果','慢查询的起点是一条具体的语句。先保留实际条件与数据量，确认问题能够稳定复现。','通过查询计划观察读取范围与过滤方式。索引是否发挥作用，需要结合条件和数据分布来判断。','在相同条件下比较优化前后的结果与开销，同时检查写入成本。一次复盘，也应该留下验证过程。'],
 6:['输入之外的时间','给复盘留个位置','慢慢形成自己的节奏','持续学习不等于始终输入。读过的内容，需要经过练习、整理和遗忘，才会变成自己的理解。','每天留下十分钟，写下一个新的发现和一个仍然困惑的问题。少量但明确的复盘，比勉强补齐很多记录更容易坚持。','不急着给成长一个结论。把注意力放回今天可以完成的一件小事，慢一点，也可以走得更稳。']}
 const b=bodies[post.id];return `<p>这是一篇用于展示阅读排版的示例${typeNames[post.type]}，内容与记录均不来自个人数据库。</p>${b.slice(0,3).map((heading,i)=>`<h2 id="part-${i+1}"><span class="section-no">0${i+1}</span>${heading}</h2><p>${b[i+3]}</p>${i===1?'<div class="callout">把值得留下的理解，写成以后还能找到的文字。</div>':''}`).join('')}`
}
function headingsFor(post){return post.id===1?['一次请求的旅程','给接口一份清晰的约定','把错误当作流程的一部分']:{2:['先写下问题','为知识建立连接','留下一条可复用的路径'],3:['从使用场景出发','理解数据结构的取舍','用小例子验证选择'],4:['一个普通的下午','走慢一点看到什么','留给今天的一句话'],5:['先看见真正的问题','读懂查询计划','验证优化的结果'],6:['输入之外的时间','给复盘留个位置','慢慢形成自己的节奏']}[post.id]}
function article(){const post=posts.find(p=>p.id===state.postId)??posts[0];const toc=`<ul class="toc-list">${headingsFor(post).map((h,i)=>`<li><a href="#part-${i+1}" class="${i===0?'active':''}"><span class="mono">0${i+1}</span>　${h}</a></li>`).join('')}</ul>`;const next=posts[post.id%posts.length]
 return `${header('article')}<main class="wrap article-page"><div class="breadcrumb"><a href="#home" data-screen="home">首页</a><span>/</span><a href="#entries" data-home-type="${post.type}">${typeNames[post.type]}</a><span>/</span><span>${post.category}</span></div><div class="reading-layout"><article><header class="article-heading"><div class="row"><span class="badge">${typeNames[post.type]}</span><span class="eyebrow" style="font-size:9px">${post.category}</span></div><h1>${escapeHtml(post.title)}</h1><p class="article-summary">${escapeHtml(post.summary)}</p><div class="article-author"><span class="author-dot">f</span><span>firefly1v</span><span>·</span><time>${post.date}</time><span>·</span><span>约 ${post.minutes} 分钟阅读</span><span>· 示例内容</span></div><div class="tags">${tags(post.tags)}</div><details class="mobile-toc"><summary>本文目录 · ${headingsFor(post).length} 个章节</summary>${toc}</details></header><div class="prose">${articleBody(post)}</div><footer class="article-end"><p>感谢阅读。希望这点微光，也能照亮你走过的一小段路。</p><a class="next-post" href="#article" data-post="${next.id}"><div><small>NEXT ENTRY / 下一篇</small>${escapeHtml(next.title)}</div>${icon('arrow')}</a></footer></article><aside class="reading-sidebar"><div class="sticky-toc"><h2 class="toc-title">ON THIS PAGE / 本文目录</h2>${toc}<p class="reading-note">把一篇文章读完，<br>也给自己留一点思考的时间。</p><div class="reading-progress"><span></span></div><p class="reading-percent">已读 <span>0</span>%</p><hr class="divider"><button class="tag" data-action="top">${icon('up')} 回到顶部</button></div></aside></div>${footer()}</main>`}

function markdownPreview(raw){return escapeHtml(raw).split(/```[a-z]*\n?/).map((part,i)=>i%2?`<div class="code-block"><pre><code>${part}</code></pre></div>`:part.split('\n').map(line=>line.startsWith('## ')?`<h2>${line.slice(3)}</h2>`:line.startsWith('# ')?`<h2>${line.slice(2)}</h2>`:line.startsWith('&gt; ')?`<div class="callout">${line.slice(5)}</div>`:line.startsWith('- ')?`<p>• ${line.slice(2)}</p>`:line?`<p>${line.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')}</p>`:'').join('')).join('')}
function editor(){const isPublished=draft.status==='PUBLISHED';const writing=state.adminPage==='write'
 return `<div class="admin-shell"><aside class="admin-sidebar"><a href="#home" data-screen="home" class="wordmark"><span class="wordmark-symbol">f</span><span><span class="wordmark-title">萤火手记</span><span class="wordmark-small">CONTENT STUDIO</span></span></a><div><p class="nav-caption">WORKSPACE</p><nav class="admin-nav" aria-label="管理导航"><button class="${!writing?'active':''}" data-admin="list">${icon('grid')}文章管理</button><button class="${writing?'active':''}" data-admin="write">${icon('edit')}写文章</button></nav></div><div class="admin-user"><div class="row"><span class="author-dot">f</span><div>firefly1v<br><small class="muted">个人写作空间</small></div></div><a href="#home" data-screen="home" class="tag" style="margin-top:20px">← 返回前台</a></div></aside><main class="admin-main"><nav class="admin-mobile-nav" aria-label="手机管理导航"><button data-admin="list" class="${!writing?'active':''}">文章管理</button><button data-admin="write" class="${writing?'active':''}">写文章</button><span class="spacer"></span><button data-screen="home">返回前台</button></nav><header class="admin-topbar"><div><h1>${writing?'写下一点新的发现':'文章管理'}</h1><span class="meta">${writing?'ARTICLE / EDITOR':'CONTENT / ARTICLES'}</span></div><div class="row">${writing?`<button class="btn small" data-action="save">${isPublished ? '保存修改' : '保存草稿'}</button><button class="btn primary small" data-action="publish" ${isPublished?'disabled':''}>${isPublished?'已发布':`发布文章 ${icon('arrow')}`}</button>`:'<button class="btn primary small" data-admin="write">写文章 ＋</button>'}</div></header>
 ${writing?`<div class="editor-body"><section class="editor-main"><label aria-label="文章标题"><input class="editor-title" id="draft-title" aria-label="文章标题" value="${escapeHtml(draft.title)}" placeholder="给这篇文章起个名字…" maxlength="200"></label><div class="editor-meta"><span class="badge" id="draft-status">${isPublished?'已公开':'草稿'}</span><span id="saved-state">${escapeHtml(JSON.stringify(draft)===savedDraft?state.savedAt:'有未保存的修改')}</span><span class="spacer"></span><button class="tag" data-action="reset-draft">恢复上次保存</button></div><p class="error-text editor-errors" id="editor-error" role="alert" hidden></p><div class="writing-panel"><div class="editor-toolbar" role="toolbar" aria-label="Markdown 工具栏"><button data-insert="heading" aria-label="插入二级标题">H₂</button><button data-insert="bold" aria-label="插入加粗"><strong>B</strong></button><button data-insert="list" aria-label="插入列表">≡</button><button data-insert="code" aria-label="插入代码块">&lt;/&gt;</button><span class="spacer"></span><button class="view-toggle ${state.editorView==='edit'?'active':''}" data-editor-view="edit">编辑</button><button class="view-toggle ${state.editorView==='preview'?'active':''}" data-editor-view="preview">预览</button></div><textarea id="draft-content" class="editor-textarea" aria-label="Markdown 正文" spellcheck="false" ${state.editorView==='preview'?'hidden':''}>${escapeHtml(draft.content)}</textarea><div class="editor-preview prose" ${state.editorView==='preview'?'':'hidden'}>${markdownPreview(draft.content)}</div><div class="editor-statusbar"><span>Markdown</span><span id="word-count">${draft.content.length} 字符</span></div></div></section><aside class="editor-side"><section><h2 class="settings-heading">文章设置</h2><div class="input-row"><label>栏目<select id="draft-type">${Object.entries(typeNames).map(([v,l])=>`<option value="${v}" ${draft.type===v?'selected':''}>${l}</option>`).join('')}</select></label><label>分类<select id="draft-category">${['Spring Boot','Java','MySQL','学习方法','生活记录','未分类'].map(c=>`<option ${c===draft.category?'selected':''}>${c}</option>`).join('')}</select></label></div></section><section><h2 class="settings-heading">标签 <span class="muted">/ 可多选</span></h2><div class="tag-picker">${[...new Set(posts.flatMap(post=>post.tags))].map(t=>`<label><input type="checkbox" name="draft-tag" value="${t}" ${draft.tags.includes(t)?'checked':''}>${t}</label>`).join('')}</div></section><section><h2 class="settings-heading">文章摘要</h2><label><span class="muted">用一两句话，留下阅读的理由。</span><textarea id="draft-summary" aria-label="文章摘要" maxlength="500">${escapeHtml(draft.summary)}</textarea></label></section><section><h2 class="settings-heading">文章封面</h2><button class="cover-choice" data-action="choose-cover" aria-label="更换文章封面">${cover(draft.cover,'当前文章')}<span class="cover-action"><span>更换封面</span></span></button></section><p class="editor-help">内容会以 Markdown 格式保存。<br>发布之前，请确认正文与公开范围。${isPublished?'<br><button class="tag" data-action="withdraw">撤回为草稿</button>':''}</p></aside></div>`:adminList()}</main></div>`}
function adminList(){return `<section class="admin-content"><div class="section-heading"><div><h2>全部记录</h2><p class="muted" style="font-size:12px;margin-top:7px">在这里整理已经写下的内容。</p></div><span class="meta">07 示例记录</span></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>标题</th><th>状态</th><th class="hide-mobile">栏目</th><th class="hide-mobile">更新时间</th><th>操作</th></tr></thead><tbody><tr><td>${escapeHtml(draft.title)||'未命名文章'}<div class="post-type">当前编辑记录</div></td><td><span class="badge">${draft.status==='DRAFT'?'草稿':'已公开'}</span></td><td class="hide-mobile">${typeNames[draft.type]}</td><td class="hide-mobile mono">刚刚</td><td><button class="tag" data-admin="write">继续编辑</button></td></tr>${posts.map(p=>`<tr><td>${p.title}<div class="post-type">${p.category}</div></td><td><span class="tag">已公开</span></td><td class="hide-mobile">${typeNames[p.type]}</td><td class="hide-mobile mono">${p.date}</td><td><button class="tag" data-edit-post="${p.id}">编辑</button></td></tr>`).join('')}</tbody></table></div></section>`}
function system(){return `${header()}<main class="wrap system-page"><div class="eyebrow">DESIGN FOUNDATION / 01</div><h1>让每一页，说同一种语言。</h1><p class="system-intro">炭黑、薄荷绿、自然留白和清晰文字。站名“萤火手记”及以下个人文案为本轮提案，正式使用前可替换；图像均为本样稿原创矢量图。</p><section class="system-section"><h2>01 / 配色</h2><div class="swatches">${[['页面背景','#101619'],['内容表面','#172024'],['主要文字','#EDF1ED'],['次要文字','#A2B0AE'],['强调色','#B7D8BD'],['错误提示','#F5AAA4']].map(([label,color])=>`<div><div class="swatch-color" style="background:${color}"></div><span>${label}</span><code>${color}</code></div>`).join('')}</div></section><section class="system-section"><h2>02 / 排版与阅读</h2><div class="type-samples"><h1 style="font-size:36px;font-weight:550">页面标题 · 把思考留下</h1><h2 style="font-size:24px;font-weight:550">章节标题 · 一次请求的旅程</h2><p style="font-size:17px;line-height:1.9;max-width:730px;color:#ced8d4">正文以 17px 左右、1.9 倍行高为起点。宽屏阅读区保持舒适的行长；手机独立重排，目录与辅助信息按需展开。</p><span class="meta">元信息 11px / 2026.10.15 · 约 8 分钟</span></div></section><section class="system-section"><h2>03 / 操作层级</h2><div class="row"><button class="btn primary" data-demo-toast="主要操作状态">发布文章 ${icon('arrow')}</button><button class="btn" data-demo-toast="次要操作状态">保存草稿</button><button class="btn quiet" data-demo-toast="轻操作状态">取消</button><button class="btn" disabled>保存中…</button><span class="badge">草稿</span><span class="tag">#Java</span></div></section><section class="system-section"><h2>04 / 页面状态</h2><div class="state-examples"><div class="state-box"><h3>正在整理内容…</h3><div class="skeleton" style="width:72%"></div><div class="skeleton"></div><div class="skeleton" style="width:88%"></div><span class="meta">加载状态示意</span></div><div class="state-box"><h3>暂时没有找到这条记录</h3><p>换一个关键词，或清空筛选继续看看。</p><button class="btn small" data-screen="home">返回文章</button></div><div class="state-box"><h3>内容暂时没能加载</h3><p>保留当前阅读位置，稍后再试一次。</p><button class="btn small" data-demo-toast="样稿重试成功">重新加载</button></div><div class="state-box"><h3>这一页暂时不在这里</h3><p>文章可能尚未公开，或者链接发生了变化。</p><button class="btn small" data-screen="home">回到首页</button></div></div></section>${footer()}</main>`}

function toast(text,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=text;el.classList.toggle('error',error);el.hidden=false;toastTimer=setTimeout(()=>{el.hidden=true},2800)}
function openModal(title,content){$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal()}
function navigate(screen,scroll=true){state.screen=screen;history.replaceState(null,'','#'+screen);render();if(scroll)window.scrollTo({top:0,behavior:'instant'})}
function render(){tocObserver?.disconnect();app.innerHTML=({home,article,editor,system}[state.screen]??home)();document.querySelectorAll('.prototype-tabs button').forEach(b=>{if(b.dataset.screen===state.screen)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.title=state.screen==='editor'?'写作后台 · 萤火手记样稿':state.screen==='article'?`${posts.find(p=>p.id===state.postId)?.title} · 萤火手记样稿`:'萤火手记 · 第二版视觉样稿';if(state.screen==='article'){tocObserver=new IntersectionObserver(entries=>{for(const entry of entries){if(entry.isIntersecting)document.querySelectorAll('.toc-list a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+entry.target.id))}},{rootMargin:'0px 0px -60% 0px'});document.querySelectorAll('.prose h2[id]').forEach(h=>tocObserver.observe(h))}updateProgress()}
function scrollEntries(){requestAnimationFrame(()=>$('#entries')?.scrollIntoView({behavior:'smooth',block:'start'}))}
function collectDraft(){const title=$('#draft-title');if(!title)return;draft.title=title.value;draft.content=$('#draft-content').value;draft.summary=$('#draft-summary').value;draft.type=$('#draft-type').value;draft.category=$('#draft-category').value;draft.tags=[...document.querySelectorAll('[name=draft-tag]:checked')].map(e=>e.value)}
function save(publish=false){collectDraft();const error=$('#editor-error');if(!draft.title.trim()||!draft.content.trim()){error.hidden=false;error.textContent='请填写文章标题和正文，再保存。';toast('请补全标题和正文',true);return}draft.title=draft.title.trim();draft.status=publish?'PUBLISHED':draft.status;savedDraft=JSON.stringify(draft);state.savedAt='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});render();toast(publish?'文章已发布 · 样稿演示':draft.status==='PUBLISHED'?'修改已保存 · 样稿演示':'草稿已保存 · 样稿演示')}
function modalContent(name){
 if(name==='about')return ['关于 firefly1v',`<div class="row" style="margin-bottom:22px"><span class="avatar">f</span><div><h3>萤火手记</h3><span class="eyebrow">FIREFLY / FIELD NOTES</span></div></div><div class="dialog-content-copy">你好，我是 firefly1v。这里用于整理学习过程中的笔记，记录思考与心得，也保留愿意公开的生活片段。<br><br>本站沿用你的现有昵称与 GitHub 链接；站名与个人介绍为第二版设计提案，可在正式实现前调整。</div><hr class="divider"><a class="btn" href="https://github.com/InInNHD/PersonalWebsite2" target="_blank" rel="noopener noreferrer">${icon('github')} 查看项目 ↗</a>`]
 if(name==='archive')return ['记录的时间线',`<div class="eyebrow">2026 / 示例归档</div><div class="dialog-toc">${posts.map(p=>`<a href="#article" data-post="${p.id}"><span class="meta">${p.date}</span>　${p.title}</a>`).join('')}</div>`]
 return ['资源收藏',`<p class="dialog-content-copy">工具与文档的展示示例。正式资源页将在后续轮次完整设计。</p><hr class="divider"><div class="dialog-toc">${[['Vue 官方文档','https://vuejs.org/','前端学习'],['Spring 官方文档','https://spring.io/projects/spring-boot','后端开发'],['MDN Web Docs','https://developer.mozilla.org/zh-CN/','基础参考']].map(([title,url,desc])=>`<a href="${url}" target="_blank" rel="noopener noreferrer"><span class="meta">${desc}</span><br>${title} ↗</a>`).join('')}</div>`]
}
document.addEventListener('click',async event=>{
 const button=event.target.closest('button,a');if(!button)return
 if(button.dataset.screen){event.preventDefault();collectDraft();navigate(button.dataset.screen);return}
 if(button.dataset.device){canvas.classList.toggle('phone',button.dataset.device==='mobile');document.querySelectorAll('[data-device]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));return}
 if(button.dataset.post){event.preventDefault();modal.close();state.postId=Number(button.dataset.post);navigate('article');return}
 if('homeType'in button.dataset){event.preventDefault();state.type=button.dataset.homeType;state.category='';state.keyword='';navigate('home',false);scrollEntries();return}
 if('type'in button.dataset){state.type=button.dataset.type;render();return}
 if(button.dataset.category){event.preventDefault();state.category=button.dataset.category;state.type='';state.filters=true;navigate('home',false);scrollEntries();return}
 if(button.dataset.tagSearch){event.preventDefault();state.keyword=button.dataset.tagSearch;state.type='';state.category='';state.filters=true;navigate('home',false);scrollEntries();return}
 if(button.dataset.modal){event.preventDefault();openModal(...modalContent(button.dataset.modal));return}
 if(button.dataset.admin){collectDraft();state.adminPage=button.dataset.admin;render();return}
 if(button.dataset.editorView){collectDraft();state.editorView=button.dataset.editorView;render();return}
 if(button.dataset.editPost){const post=posts.find(p=>p.id===Number(button.dataset.editPost));draft={...draft,title:post.title,summary:post.summary,type:post.type,category:post.category,tags:[...post.tags],cover:post.cover,status:'PUBLISHED',content:'# '+post.title+'\n\n'+post.summary+'\n\n## 写下新的发现\n\n在这里继续整理你的理解。'};savedDraft=JSON.stringify(draft);state.adminPage='write';state.savedAt='已载入示例';render();return}
 if(button.dataset.insert){collectDraft();const input=$('#draft-content');const inserts={heading:'\n## 新的章节\n',bold:'**加粗文字**',list:'\n- 新的条目\n',code:'\n```java\n// 在这里写代码\n```\n'};const insertion=inserts[button.dataset.insert];const start=input.selectionStart,end=input.selectionEnd;draft.content=input.value.slice(0,start)+insertion+input.value.slice(end);state.editorView='edit';render();const next=$('#draft-content');next.focus();next.setSelectionRange(start+insertion.length,start+insertion.length);$('#saved-state').textContent='有未保存的修改';return}
 if(button.dataset.cover){collectDraft();draft.cover=button.dataset.cover;modal.close();render();$('#saved-state').textContent='有未保存的修改';return}
 if(button.dataset.demoToast){toast(button.dataset.demoToast);return}
 switch(button.dataset.action){
  case'menu':{const nav=$('.site-nav');nav.classList.toggle('open');button.setAttribute('aria-expanded',String(nav.classList.contains('open')));break}
  case'filters':state.filters=!state.filters;render();break
  case'clear':state.type='';state.category='';state.keyword='';render();break
  case'top':window.scrollTo({top:0,behavior:'smooth'});break
  case'copy-code':try{await navigator.clipboard.writeText(sampleCode);button.textContent='已复制';toast('代码已复制')}catch{toast('复制未完成，请手动选择代码',true)}break
  case'zoom-flow':openModal('一次请求的旅程',flowSvg()+'<p class="dialog-content-copy">浏览器发送请求，后端执行业务校验，再从数据库读取内容并返回。</p>');break
  case'search':openModal('找一条记录',`<form class="search-form" id="global-search"><label>搜索标题、摘要或标签<input autofocus type="search" name="q" placeholder="例如：Java、学习方法" autocomplete="off"></label><button class="btn primary" type="submit">搜索记录 ${icon('search')}</button></form><div id="search-results" class="search-results" aria-live="polite"></div>`);break
  case'save':save(false);break
  case'publish':save(true);break
  case'withdraw':collectDraft();draft.status='DRAFT';savedDraft=JSON.stringify(draft);state.savedAt='已撤回 · 样稿演示';render();toast('已撤回为草稿 · 样稿演示');break
  case'choose-cover':openModal('选择一张示例封面',`<div class="cover-options">${[['request','请求与协作'],['notes','知识与笔记'],['java','Java 与代码'],['diary','生活与片刻']].map(([v,t])=>`<button data-cover="${v}">${cover(v,t)}<span>${t}</span></button>`).join('')}</div>`);break
  case'reset-draft':draft=JSON.parse(savedDraft);render();toast('已恢复到上次保存的示例');break
 }
})
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target;if(form.id==='filters'){state.keyword=form.elements.keyword.value.trim();state.category=form.elements.category.value;render()}else if(form.id==='global-search'){const q=form.elements.q.value.trim().toLowerCase();const found=posts.filter(p=>[p.title,p.summary,...p.tags].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=found.length?found.map(p=>`<button data-post="${p.id}">${escapeHtml(p.title)}<small>${typeNames[p.type]} · ${p.date}</small></button>`).join(''):'<p class="muted">暂时没有找到记录，试试其他关键词。</p>'}})
app.addEventListener('input',event=>{if(state.screen==='editor'){collectDraft();const saved=$('#saved-state');if(saved)saved.textContent=JSON.stringify(draft)===savedDraft?state.savedAt:'有未保存的修改';const count=$('#word-count');if(count)count.textContent=draft.content.length+' 字符'}})
$('#close-modal').addEventListener('click',()=>modal.close())
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}})
function updateProgress(){if(state.screen!=='article')return;const article=$('.reading-layout>article');if(!article)return;const rect=article.getBoundingClientRect();const amount=Math.max(0,Math.min(100,Math.round((-rect.top)/(article.offsetHeight-innerHeight)*100)));const bar=$('.reading-progress span'),label=$('.reading-percent span');if(bar)bar.style.width=amount+'%';if(label)label.textContent=String(amount)}
window.addEventListener('scroll',updateProgress,{passive:true})
render()
